class Solution {
public:
    std::vector<int> divisibilityArray(std::string word, int m) {
        std::vector<int> res;
        res.reserve(word.size());
        long long rem = 0;
        for (char ch : word) {
            rem = (rem * 10 + (ch - '0')) % m;
            res.push_back(rem == 0 ? 1 : 0);
        }
        return res;
    }
};

class Solution {
    public int[] divisibilityArray(String word, int m) {
        int n = word.length();
        int[] res = new int[n];
        long rem = 0;
        for (int i = 0; i < n; i++) {
            rem = (rem * 10 + (word.charAt(i) - '0')) % m;
            res[i] = rem == 0 ? 1 : 0;
        }
        return res;
    }
}

